-- Keep the echo clinic guidance identical in booking, tracking and receipts.
UPDATE public.clinics
SET instructions = E'للأطفال من 6 شهور حتى 3 سنوات: يجب أن يكون الطفل خاليًا من أعراض البرد.\nالتأكد من عدم وجود كحة أو رشح/نزلة برد أو ارتفاع درجة الحرارة.\nليلة الاختبار: نوم الطفل الساعة 12 مساءً وإيقاظه الساعة 4 فجراً وعدم السماح له بالنوم حتى الوصول للمستشفى حتى يمكنه النوم أثناء الفحص عند الحاجة وتهيئته للاختبار.\nالحضور للمستشفى مبكرًا الساعة 8:30 صباحًا أمام عيادة القلب بالدور الرابع.\nإحضار كلورال هيدرات 10% إذا قرر الطبيب استخدامه، ويُعطى فقط تحت إشراف طبيب عيادة القلب حسب الحالة.',
    updated_at = timezone('utc'::text, now())
WHERE id = 'echo';

UPDATE public.clinic_services
SET instructions = E'للأطفال من 6 شهور حتى 3 سنوات: يجب أن يكون الطفل خاليًا من أعراض البرد.\nالتأكد من عدم وجود كحة أو رشح/نزلة برد أو ارتفاع درجة الحرارة.\nليلة الاختبار: نوم الطفل الساعة 12 مساءً وإيقاظه الساعة 4 فجراً وعدم السماح له بالنوم حتى الوصول للمستشفى حتى يمكنه النوم أثناء الفحص عند الحاجة وتهيئته للاختبار.\nالحضور للمستشفى مبكرًا الساعة 8:30 صباحًا أمام عيادة القلب بالدور الرابع.\nإحضار كلورال هيدرات 10% إذا قرر الطبيب استخدامه، ويُعطى فقط تحت إشراف طبيب عيادة القلب حسب الحالة.',
    updated_at = timezone('utc'::text, now())
WHERE id IN ('echo_first_visit', 'echo_follow_up');
